const LEDGER_JSON_WHITESPACE = /^[\u0009\u000D\u0020]*$/;

async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  const fragments = [];

  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let hasPendingData = false;
  let normalEOF = false;

  async function processLine(finalFragment) {
    const text =
      fragments.length === 0
        ? finalFragment
        : fragments.join("") + finalFragment;

    fragments.length = 0;

    if (LEDGER_JSON_WHITESPACE.test(text)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return false;
    }

    const result = await visitor({ line, value });
    accepted++;
    return result === false;
  }

  try {
    while (true) {
      const result = await reader.read();

      if (result.done) {
        const tail = decoder.decode();

        if (tail.length !== 0) {
          fragments.push(tail);
          hasPendingData = true;
        }

        if (hasPendingData) {
          const stopped = await processLine("");
          if (stopped) {
            return { accepted, rejected, stopped: true };
          }
        }

        normalEOF = true;
        return { accepted, rejected, stopped: false };
      }

      const text = decoder.decode(result.value, { stream: true });
      let start = 0;

      for (let index = 0; index < text.length; index++) {
        if (text.charCodeAt(index) !== 10) {
          continue;
        }

        const stopped = await processLine(text.slice(start, index));
        if (stopped) {
          return { accepted, rejected, stopped: true };
        }

        line++;
        hasPendingData = false;
        start = index + 1;
      }

      if (start < text.length) {
        fragments.push(text.slice(start));
        hasPendingData = true;
      }
    }
  } finally {
    if (!normalEOF) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
